& 'icacls' "$mainOSDrive\scratchDir\ProgramData\Microsoft\Windows Defender\Definition Updates" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q'

Write-Host "Taking ownership of the Windows folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchdir\Windows" '/A' '/R' '/D' 'Y'
& 'icacls' "$mainOSDrive\scratchdir\Windows" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q'

Write-Host "Taking ownership of the RtBackup folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchDir\Windows\System32\LogFiles\WMI\RtBackup" '/A' '/R' '/D' 'Y'
& 'icacls' "$mainOSDrive\scratchDir\Windows\System32\LogFiles\WMI\RtBackup" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q'
Write-host "Complete!"

Write-Host "Mounting complete! Performing removal of applications..." -ForegroundColor Cyan

# Retrieve provisioned packages cleanly using DISM with English output
$dismOutput = & dism /English "/image:$($env:SystemDrive)\scratchdir" /Get-ProvisionedAppxPackages

$packages = @()
foreach ($line in $dismOutput) {
    if ($line -match '^\s*PackageName\s*:\s*(.+)$') {
        $packages += $Matches[1].Trim()
    }
}

# Keep only these runtime packages
$keepPrefixes = @(
    "Microsoft.VCLibs.",
    "Microsoft.UI.Xaml.",
    "Microsoft.NET.Native.Framework.",
    "Microsoft.NET.Native.Runtime.",
    "Microsoft.WindowsAppRuntime."
)

# Filter packages to remove
$packagesToRemove = foreach ($package in $packages) {
    $keep = $false
    foreach ($prefix in $keepPrefixes) {
        if ($package.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
            $keep = $true
            break
        }
    }
    if (-not $keep) {
        $package
    }
}

# Loop and remove unwanted provisioned packages
foreach ($package in $packagesToRemove) {
    Write-Host "Removing package: $package" -ForegroundColor Yellow

    & dism /English `
        "/image:$($env:SystemDrive)\scratchdir" `
        /Remove-ProvisionedAppxPackage `
        "/PackageName:$package"
        
    if ($LASTEXITCODE -ne 0) {
        Write-Warning "Failed to remove package: $package"
    }
}

Write-Host "App removal process finished." -ForegroundColor Green

Write-Host "Attempting to remove leftover WindowsApps folders..."
foreach ($package in $packagesToRemove) {
    $folderPath = Join-Path "$scratchDir\Program Files\WindowsApps" $package

    if (Test-Path $folderPath) {
        Write-Host "Deleting folder: $package"
        Remove-Item $folderPath -Recurse -Force -ErrorAction SilentlyContinue
    }
}

Write-Host "Removing of system apps complete! Now proceeding to removal of system packages..."
