Write-Host "Micro 11 Barebones Registry Tweaks have been applied!"

Write-Host "Unloading registry hives..."
reg unload HKLM\zCOMPONENTS 2>$null
reg unload HKLM\zDEFAULT 2>$null
reg unload HKLM\zNTUSER 2>$null
reg unload HKLM\zSOFTWARE 2>$null
reg unload HKLM\zSYSTEM 2>$null

Write-Host "Cleaning up image..."
& 'dism' '/English' "/image:$mainOSDrive\scratchdir" '/Cleanup-Image' '/StartComponentCleanup' '/ResetBase' >null
Write-Host "Cleanup complete."
Write-Host ' '
Write-Host "Unmounting image..."
& 'dism' '/English' '/unmount-image' "/mountdir:$mainOSDrive\scratchdir" '/commit'
Write-Host "Exporting image..."
& 'dism' '/English' '/Export-Image' "/SourceImageFile:$mainOSDrive\Micro 11 Barebones\sources\install.wim" "/SourceIndex:$index" "/DestinationImageFile:$mainOSDrive\Micro 11 Barebones\sources\install2.wim" '/compress:max'
Remove-Item -Path "$mainOSDrive\Micro 11 Barebones\sources\install.wim" -Force >null
Rename-Item -Path "$mainOSDrive\Micro 11 Barebones\sources\install2.wim" -NewName "install.wim" >null
Write-Host "Windows image completed. Continuing with boot.wim."
Start-Sleep -Seconds 2
Clear-Host
Write-Host "Mounting boot image:"
$wimFilePath = "$($env:SystemDrive)\Micro 11 Barebones\sources\boot.wim" 
& takeown "/F" $wimFilePath >null
& icacls $wimFilePath "/grant" "$($adminGroup.Value):(F)"
Set-ItemProperty -Path $wimFilePath -Name IsReadOnly -Value $false
& 'dism.exe' '/English' '/Delete-Image' "/ImageFile:$($env:SystemDrive)\Micro 11 Barebones\sources\boot.wim" '/Index:1'
Write-Host "Getting image information:"
&  'dism' '/English' "/Get-WimInfo" "/wimfile:$mainOSDrive\Micro 11 Barebones\sources\boot.wim"
& 'dism.exe' '/English' '/mount-image' "/imagefile:$mainOSDrive\Micro 11 Barebones\sources\boot.wim" '/index:1' "/mountdir:$mainOSDrive\scratchdir"

Write-Host "Taking ownership of the Program Files folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchDir\Program Files" '/A' '/R' '/D' 'Y'
& 'icacls' "$mainOSDrive\scratchDir\Program Files" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q'

Write-Host "Taking ownership of the Program Files (x86) folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchdir\Program Files (x86)" '/A' '/R' '/D' 'Y'
& 'icacls' "$mainOSDrive\scratchdir\Program Files (x86)" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q'

Write-Host "Taking ownership of the ProgramData folder. This might take a while..."
