& 'icacls' "$mainOSDrive\scratchDir\sources" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q'

Write-Host "Taking ownership of the Users folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchDir\Users" '/A' '/R' '/D' 'Y'
& 'icacls' "$mainOSDrive\scratchDir\Users" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q'


Write-Host "Taking ownership of the Windows folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchdir\Windows" '/A' '/R' '/D' 'Y'
& 'icacls' "$mainOSDrive\scratchdir\Windows" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q'

Write-Host "Mounting complete! Performing Boot Wim Agressive Manual Deletions..."
Remove-Item -Path "$scratchDir\Program Files" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Program Files (x86)" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\ProgramData" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Users" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\sources\recovery" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\AppCompat" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\apppatch" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\Branding" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\CbsTemp" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\DiagTrack" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\en-US" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\Fonts" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\Help" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\L2Schemas" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\LiveKernelReports" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\Logs" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\Microsoft.NET" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$scratchDir\Windows\PLA" -Recurse -Force -ErrorAction SilentlyContinue
