Write-Host "Removal complete!"
Start-Sleep -Seconds 2
Clear-Host
Write-Host "Taking ownership of the WinSxS folder. This might take a while..."
& 'takeown' '/f' "$mainOSDrive\scratchdir\Windows\WinSxS" '/A' '/R' '/D' 'Y'
& 'icacls' "$mainOSDrive\scratchdir\Windows\WinSxS" '/grant' "$($adminGroup.Value):(F)" '/T' '/C' '/Q'
Write-Host "Complete!"
Write-Host "Preparing Boot WinSxS...."

$folderPath = Join-Path -Path $mainOSDrive -ChildPath "\scratchdir\Windows\WinSxS_edit"
$sourceDirectory = "$mainOSDrive\scratchdir\Windows\WinSxS"
$destinationDirectory = "$mainOSDrive\scratchdir\Windows\WinSxS_edit"

New-Item -Path $folderPath -ItemType Directory -Force | Out-Null

if ($architecture -eq "amd64") {
    $dirsToCopy = @(
        "amd64_microsoft.windows.common-controls_6595b64144ccf1df_*",
        "amd64_microsoft.windows.gdiplus_6595b64144ccf1df_*"
    )

    # Copy each directory
    foreach ($dir in $dirsToCopy) {
        $sourceDirs = Get-ChildItem -Path $sourceDirectory -Filter $dir -Directory
        foreach ($sourceDir in $sourceDirs) {
            $destDir = Join-Path -Path $destinationDirectory -ChildPath $sourceDir.Name
            Write-Host "Copying $($sourceDir.FullName) to $destDir"
            Copy-Item -Path $sourceDir.FullName -Destination $destDir -Recurse -Force
        }
    }

    # Copy only required manifests
    $manifestPath = Join-Path $sourceDirectory "Manifests"
    $destPath = Join-Path $destinationDirectory "Manifests"
    New-Item -ItemType Directory -Path $destPath -Force | Out-Null
    
    $keep = @(
        "amd64_microsoft.windows.i..utomation.proxystub_*","amd64_microsoft.windows.isolationautomation_*","amd64_microsoft-windows-international-core_*","amd64_microsoft.windows.common-controls_*","amd64_microsoft.windows.c..-controls.resources_*_en-us_*","amd64_microsoft.windows.gdiplus_*","amd64_microsoft.windows.systemcompatible_*","amd64_microsoft-windows-servicingstack_*","x86_microsoft-windows-servicingstack_*"
    )
    
    foreach ($pattern in $keep) {
        Get-ChildItem $manifestPath -Filter $pattern -File -ErrorAction SilentlyContinue | Copy-Item -Destination $destPath -Force
    }
}
elseif ($architecture -eq "arm64") {
    $dirsToCopy = @(
        "arm64_microsoft.windows.common-controls_6595b64144ccf1df_*",
        "arm64_microsoft.windows.gdiplus_6595b64144ccf1df_*"
    )
    
    # Add ARM64 specific copy logic here if needed
    Write-Host "ARM64 architecture selected. Implement copy routine analogously to AMD64."
}

Write-Host "Deleting WinSxS. This may take a while..."
        Remove-Item -Path $mainOSDrive\scratchdir\Windows\WinSxS -Recurse -Force

Rename-Item -Path $mainOSDrive\scratchdir\Windows\WinSxS_edit -NewName $mainOSDrive\scratchdir\Windows\WinSxS
Write-Host "Complete!"

Write-Host "Loading Boot Wim registry..."
reg load HKLM\zCOMPONENTS $mainOSDrive\scratchdir\Windows\System32\config\COMPONENTS
reg load HKLM\zDEFAULT $mainOSDrive\scratchdir\Windows\System32\config\default
reg load HKLM\zNTUSER $mainOSDrive\scratchdir\Users\Default\ntuser.dat
reg load HKLM\zSOFTWARE $mainOSDrive\scratchdir\Windows\System32\config\SOFTWARE
reg load HKLM\zSYSTEM $mainOSDrive\scratchdir\Windows\System32\config\SYSTEM
Write-Host "Bypassing system requirements on the Boot wim image"
& 'reg' 'add' 'HKLM\zDEFAULT\Control Panel\UnsupportedHardwareNotificationCache' '/v' 'SV1' '/t' 'REG_DWORD' '/d' '0' '/f' >null
& 'reg' 'add' 'HKLM\zDEFAULT\Control Panel\UnsupportedHardwareNotificationCache' '/v' 'SV2' '/t' 'REG_DWORD' '/d' '0' '/f' >null
& 'reg' 'add' 'HKLM\zNTUSER\Control Panel\UnsupportedHardwareNotificationCache' '/v' 'SV1' '/t' 'REG_DWORD' '/d' '0' '/f' >null
& 'reg' 'add' 'HKLM\zNTUSER\Control Panel\UnsupportedHardwareNotificationCache' '/v' 'SV2' '/t' 'REG_DWORD' '/d' '0' '/f' >null
& 'reg' 'add' 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassCPUCheck' '/t' 'REG_DWORD' '/d' '1' '/f' >null
& 'reg' 'add' 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassRAMCheck' '/t' 'REG_DWORD' '/d' '1' '/f' >null
& 'reg' 'add' 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassSecureBootCheck' '/t' 'REG_DWORD' '/d' '1' '/f' >null
& 'reg' 'add' 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassStorageCheck' '/t' 'REG_DWORD' '/d' '1' '/f' >null
& 'reg' 'add' 'HKLM\zSYSTEM\Setup\LabConfig' '/v' 'BypassTPMCheck' '/t' 'REG_DWORD' '/d' '1' '/f' >null
& 'reg' 'add' 'HKLM\zSYSTEM\Setup\MoSetup' '/v' 'AllowUpgradesWithUnsupportedTPMOrCPU' '/t' 'REG_DWORD' '/d' '1' '/f' >null
& 'reg' 'add' 'HKEY_LOCAL_MACHINE\zSYSTEM\Setup' '/v' 'CmdLine' '/t' 'REG_SZ' '/d' 'X:\sources\setup.exe' '/f' >null
Write-Host "Tweaking complete!"
Write-Host "Unmounting Registry..."
reg unload HKLM\zCOMPONENTS >null
reg unload HKLM\zDEFAULT >null
reg unload HKLM\zNTUSER >null
reg unload HKLM\zSOFTWARE >null
reg unload HKLM\zSYSTEM >null
Write-Host "Cleaning up image..."
& 'dism' '/English' "/image:$mainOSDrive\scratchdir" '/Cleanup-Image' '/StartComponentCleanup' '/ResetBase' >null
Write-Host "Cleanup complete."
Write-Host "Unmounting image..."
& 'dism' '/English' '/unmount-image' "/mountdir:$mainOSDrive\scratchdir" '/commit'
# Rebuild boot.wim after cleanup. Exporting to a new WIM physically compacts the image and removes unused/deleted data.
Write-Host "Rebuilding boot.wim to physically reduce its size..."
$bootWim = "$mainOSDrive\Micro 11 Barebones\sources\boot.wim"
$bootWimRebuilt = "$mainOSDrive\Micro 11 Barebones\sources\boot_rebuilt.wim"
if (Test-Path $bootWimRebuilt) { Remove-Item -Path $bootWimRebuilt -Force -ErrorAction SilentlyContinue }
Write-Host "Exporting boot.wim with maximum compression. This may take a while..."
& 'dism.exe' '/English' '/Export-Image' `
    "/SourceImageFile:$bootWim" '/SourceIndex:1' `
    "/DestinationImageFile:$bootWimRebuilt" '/Compress:max' '/CheckIntegrity'
if ($LASTEXITCODE -ne 0 -or -not (Test-Path $bootWimRebuilt)) {
    Write-Host "ERROR: boot.wim rebuild failed. The original boot.wim has been retained."
    exit 1
}
Write-Host "Replacing original boot.wim with rebuilt boot.wim..."
Remove-Item -Path $bootWim -Force -ErrorAction Stop
Rename-Item -Path $bootWimRebuilt -NewName "boot.wim" -ErrorAction Stop
Write-Host "Boot.wim rebuild complete."
Write-Host "Final boot.wim information:"
& 'dism.exe' '/English' '/Get-WimInfo' "/WimFile:$bootWim"

Clear-Host
Write-Host "Deleting Manual Setup Deletions..."
Remove-Item -Path "$mainOSDrive\Micro 11 Barebones\support" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$mainOSDrive\Micro 11 Barebones\autorun.inf" -Recurse -Force -ErrorAction SilentlyContinue
