Remove-Item -Path "$mainOSDrive\Micro 11 Barebones\sources\w32uires.dll" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$mainOSDrive\Micro 11 Barebones\sources\warning.gif" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$mainOSDrive\Micro 11 Barebones\sources\wdsclient.dll" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$mainOSDrive\Micro 11 Barebones\sources\wdsclientapi.dll" -Recurse -Force -ErrorAction SilentlyContinue
Remove-Item -Path "$mainOSDrive\Micro 11 Barebones\sources\wdscommonlib.dll" -Recurse -Force -ErrorAction SilentlyContinue
Clear-Host
Write-Host "The Micro 11 Barebones image is now completed. Proceeding with the making of the ISO..."
Write-Host "Creating ISO image..."
$ADKDepTools = "C:\Program Files (x86)\Windows Kits\10\Assessment and Deployment Kit\Deployment Tools\$hostarchitecture\Oscdimg"
$localOSCDIMGPath = "$PSScriptRoot\oscdimg.exe"

if ([System.IO.Directory]::Exists($ADKDepTools)) {
    Write-Host "Will be using oscdimg.exe from system ADK."
    $OSCDIMG = "$ADKDepTools\oscdimg.exe"
} else {
    Write-Host "ADK folder not found. Will be using bundled oscdimg.exe."
    
    
    $url = "https://msdl.microsoft.com/download/symbols/oscdimg.exe/3D44737265000/oscdimg.exe"

    if (-not (Test-Path -Path $localOSCDIMGPath)) {
        Write-Host "Downloading oscdimg.exe..."
        Invoke-WebRequest -Uri $url -OutFile $localOSCDIMGPath

        if (Test-Path $localOSCDIMGPath) {
            Write-Host "oscdimg.exe downloaded successfully."
        } else {
            Write-Error "Failed to download oscdimg.exe."
            exit 1
        }
    } else {
        Write-Host "oscdimg.exe already exists locally."
    }

    $OSCDIMG = $localOSCDIMGPath
}

& "$OSCDIMG" '-m' '-o' '-u2' '-udfver102' "-bootdata:2#p0,e,b$ScratchDisk\Micro 11 Barebones\boot\etfsboot.com#pEF,e,b$ScratchDisk\Micro 11 Barebones\efi\microsoft\boot\efisys.bin" "$ScratchDisk\Micro 11 Barebones" "$PSScriptRoot\Micro 11 Barebones.iso"

# Finishing up
Write-Host "Creation completed! Press any key to exit the script..."
Read-Host "Press Enter to continue"
Write-Host "Performing Cleanup..."
Remove-Item -Path "$mainOSDrive\Micro 11 Barebones" -Recurse -Force >null
Remove-Item -Path "$mainOSDrive\scratchdir" -Recurse -Force >null

# Stop the transcript
Stop-Transcript

exit
}
elseif ($input -eq 'n') {
    Write-Host "You chose not to continue. The script will now exit."
    exit
}
else {
    Write-Host "Invalid input. Please enter 'y' to continue or 'n' to exit."
}